    """min diffs over translations of b into a"""
    res=[]
    n=len(a); m=len(b[0])
    for dr in range(-(h),n):
        for dc in range(-m+1,m):
            cnt=0
            ok=True
            for ri in range(h):
                r=ri+dr
                if not(0<=r<n): continue
                for ci in range(m):
                    c=ci+dc
                    if not(0<=c<m): continue
                    if a[r][c]!=b[ri][ci]: cnt+=1
            res.append((cnt,dr,dc))
    return sorted(res)[:5]
