def best_tr(g1,g2,W):
    # best dr (row offset): g2 row maps to g1 row g1_row+dr; score diffs on overlap
    res=[]
    h1=len(g1); h2=len(g2)
    for dr in range(-h2+1,h1):
        n=sum(1 for ri in range(max(0,-dr),min(h1,h2)) if sum(1 for ci in range(W) if g1[ri][ci]!=g2[ri-dr][ci])==0)
        tot=min(h1,h2)
        mism=sum(1 for ri in range(max(0,-dr),min(h1,h2)) for ci in range(W) if g1[ri][ci]!=g2[ri-dr][ci])
        res.append((mism,dr,n,tot))
    return sorted(res)[:4]
