def solve_period(g, Ti, Tj):
    H,W=len(g),len(g[0])
    from collections import Counter
    out=[list(r_) for r_ in g]
    dev=0
    for i in range(H):
        for j in range(W):
            vals=[]
            for a in range(0,Ti,H):
                for b in range(0,Tj,W):
                    rr,cc=(i+a)%H,(j+b)%W
                    vals.append(g[rr][cc])
            pred=Counter(vals).most_common(1)[0][0]
            if g[i][j]!=pred:
                dev+=1
                out[i][j]=1
    return dev,out
