def bands_of(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r_ in g for x in r_)
    # object color = color forming short runs / pattern; bg = other
    # heuristic: bg = color of the widest contiguous horizontal run
    wds={c:max(runlen) for c,runlen in [(c,0)]}
    best_run=0
    for i,r_ in enumerate(g):
        c=None
        for jj in range(W):
            runlen=0
            while jj<W and g[r_][jj]==g[r_][max(0,jj-1)]: pass
        jj=0
        while jj<W:
            cur=g[r_][jj]; j=jj
            while j<W and g[r_][j]==cur: j+=1
            run=j-jj
            if run>best_run: best_run=run
            jj=j
        if cur in cnt: wds[cur]=max(wds.get(cur,0),run)
    # object: color whose runs are generally shorter
    keys=list(cnt); 
    obj=min(keys,key=lambda c:wds.get(c,99))
    bg=max(set(cnt)-{obj}, key=lambda c:cnt[c])
    sep=[i for i in range(H) if i==H-1 or len(set(g[i]))==1 and g[i][0]==bg]
    b=[]; cur=[]
    for i in range(H):
        if i in sep and (not cur or g[i][0]==bg):
            if cur: b.append(cur)
            cur=[]
        else: cur.append(i)
    if cur: b.append(cur)
    return bg,obj,b,sep

